function hitungBMI(){const tinggiInput=document.getElementById("bmiTinggi").value,beratInput=document.getElementById("bmiBerat").value;if(!tinggiInput||!beratInput||tinggiInput<=0||beratInput<=0)return void alert("Harap masukkan angka tinggi badan dan berat badan yang valid!");const tinggiMeter=parseFloat(tinggiInput)/100,scoreBMI=(parseFloat(beratInput)/(tinggiMeter*tinggiMeter)).toFixed(1),scoreEl=document.getElementById("bmiScoreText"),badgeEl=document.getElementById("bmiStatusBadge"),adviceEl=document.getElementById("bmiAdviceText");scoreEl.innerText=scoreBMI,scoreBMI<18.5?(badgeEl.innerText="Berat Badan Kurang (Underweight)",badgeEl.style.backgroundColor="#EBF4FF",badgeEl.style.color="#2563EB",adviceEl.innerText="Tingkatkan asupan nutrisi padat gizi, konsumsi protein seimbang, dan lakukan latihan kekuatan untuk membangun massa otot."):scoreBMI>=18.5&&scoreBMI<=24.9?(badgeEl.innerText="Berat Badan Ideal (Normal)",badgeEl.style.backgroundColor="#E7F7EE",badgeEl.style.color="#2EAD70",adviceEl.innerText="Selamat! Berat badan Anda berada dalam kategori ideal yang sehat. Pertahankan pola makan bernutrisi dan olahraga teratur."):scoreBMI>=25&&scoreBMI<=29.9?(badgeEl.innerText="Kelebihan Berat Badan (Overweight)",badgeEl.style.backgroundColor="#FEF3C7",badgeEl.style.color="#D97706",adviceEl.innerText="Perhatikan porsi kalori harian, perbanyak konsumsi serat sayur-buah, dan tingkatkan aktivitas fisik harian Anda."):(badgeEl.innerText="Kategori Obesitas (Obese)",badgeEl.style.backgroundColor="#FEE2E2",badgeEl.style.color="#DC2626",adviceEl.innerText="Disarankan berkonsultasi dengan dokter atau ahli gizi untuk merancang program penurunan berat badan yang aman.")}function resetBMI(){document.getElementById("bmiTinggi").value="",document.getElementById("bmiBerat").value="",document.getElementById("bmiScoreText").innerText="--.-";const badgeEl=document.getElementById("bmiStatusBadge");badgeEl.innerText="Menunggu Input Data",badgeEl.style.backgroundColor="#F3F4F6",badgeEl.style.color="#6B7280",document.getElementById("bmiAdviceText").innerText="Masukkan tinggi dan berat badan Anda pada formulir di sebelah kiri, lalu klik tombol Hitung BMI."}function kirimPesan(event){event.preventDefault();const nama=document.getElementById("nama").value.trim(),email=document.getElementById("email").value.trim(),subjek=document.getElementById("subjek").value.trim(),pesan=document.getElementById("pesan").value.trim(),alertBox=document.getElementById("formAlertBox");if(!(nama&&email&&subjek&&pesan))return alertBox.className="form-alert-error",alertBox.innerHTML='<i class="fa-solid fa-triangle-exclamation"></i> <strong>Perhatian:</strong> Harap isi seluruh kolom formulir kontak!',void(alertBox.style.display="block");alertBox.className="form-alert-success",alertBox.innerHTML=`<i class="fa-solid fa-circle-check"></i> Terima kasih, <strong>${nama}</strong>! Pesan Anda telah berhasil dikirim ke tim Wellora. Kami akan segera membalas ke <strong>${email}</strong>.`,alertBox.style.display="block",document.getElementById("contactForm").reset(),setTimeout((()=>{alertBox.style.display="none"}),6e3)}function keAtasHalaman(){window.scrollTo({top:0,behavior:"smooth"})}window.addEventListener("scroll",(function(){const btnTop=document.getElementById("btnBackToTop");window.scrollY>300?btnTop.style.display="flex":btnTop.style.display="none"}));const urlParams=new URLSearchParams(window.location.search),id=urlParams.get("id")||"0",artikelTerpilih=document.getElementById("artikel-"+id);artikelTerpilih?artikelTerpilih.style.display="block":document.getElementById("artikel-0").style.display="block";